INSERT INTO pedagogy_entries (id, learning_item_id, field_key, value, evidence_state, source) VALUES
  ('ped_itm_l1_m1_lesson1_common_mistakes', 'itm_l1_m1_lesson1', 'common_mistakes', 'Learners often use ''Good night'' as a greeting. It is a farewell. ''I''m name is Ana'' is the commonest first-week error: choose one form, not both.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m1_lesson2_common_mistakes', 'itm_l1_m1_lesson2', 'common_mistakes', '''I come from Brazil'' is correct but less common in speech; ''I''m from'' is the default. Article use with country names is arbitrary and must be learned, not reasoned.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m2_lesson1_common_mistakes', 'itm_l1_m2_lesson1', 'common_mistakes', 'Word order: Is there, not There is? The verb agrees with what follows, not with ''there''.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m2_lesson2_common_mistakes', 'itm_l1_m2_lesson2', 'common_mistakes', 'Many learners have one word for both distances in their first language and reach for ''this'' by default.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m3_lesson1_common_mistakes', 'itm_l1_m3_lesson1', 'common_mistakes', '''Yes, I have'' is incomplete in English: the short answer repeats the auxiliary.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m3_lesson2_common_mistakes', 'itm_l1_m3_lesson2', 'common_mistakes', 'Quarter to NINE, not quarter to eight: ''to'' looks forward. The missing -s is the most common Level I grammar error and it persists for months.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m4_lesson1_common_mistakes', 'itm_l1_m4_lesson1', 'common_mistakes', '''some'' in positives, ''any'' in questions and negatives — with the polite-offer exception (''Would you like some tea?'').', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m4_lesson2_common_mistakes', 'itm_l1_m4_lesson2', 'common_mistakes', '''How much are'' with plurals: the verb changes, ''how much'' does not become ''how many'' for price.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m5_lesson1_common_mistakes', 'itm_l1_m5_lesson1', 'common_mistakes', 'These two are confused more than any other pair at this level.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m5_lesson2_common_mistakes', 'itm_l1_m5_lesson2', 'common_mistakes', 'Start with ''Excuse me'' — the request without it sounds abrupt in English.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m6_lesson1_common_mistakes', 'itm_l1_m6_lesson1', 'common_mistakes', '''She has tall'' is the classic error: appearance uses both verbs, and which one depends on the word. Not ''How does she look like?'' — the two questions differ.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m6_lesson2_common_mistakes', 'itm_l1_m6_lesson2', 'common_mistakes', 'Possessive adjective before a noun, possessive pronoun alone.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m7_lesson1_common_mistakes', 'itm_l1_m7_lesson1', 'common_mistakes', 'Spelling changes: -y to -ied, and the doubled consonant in stopped. The -ed disappears after ''didn''t''. Learners keep it for weeks.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m7_lesson2_common_mistakes', 'itm_l1_m7_lesson2', 'common_mistakes', 'Not ''Where did you went'' — the auxiliary carries the past.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m8_lesson1_common_mistakes', 'itm_l1_m8_lesson1', 'common_mistakes', 'The infinitive marker after modals is a persistent error.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m8_lesson2_common_mistakes', 'itm_l1_m8_lesson2', 'common_mistakes', 'The overlap between the two ''going to'' uses causes real confusion here.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m9_lesson1_common_mistakes', 'itm_l1_m9_lesson1', 'common_mistakes', 'Have for the problem, feel for the state — mixing them is very common.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m9_lesson2_common_mistakes', 'itm_l1_m9_lesson2', 'common_mistakes', 'Silence or a bare ''OK'' reads as dismissal in English; the response has to acknowledge the advice.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.'),
  ('ped_itm_l1_m10_revlesson_common_mistakes', 'itm_l1_m10_revlesson', 'common_mistakes', 'Selecting the structure without a prompt is the skill this level ends on; recognising each in isolation is easier than choosing between them.', 'derived_from_curriculum', 'The confusions this lesson''''s own self-check prompts are written to catch.')ON CONFLICT (learning_item_id, field_key) DO UPDATE SET
INSERT INTO pedagogy_entries (id, learning_item_id, field_key, value, evidence_state, source) VALUES
  ('ped_itm_l1_m1_lesson1_confusable_concepts', 'itm_l1_m1_lesson1', 'confusable_concepts', 'hi: Friendly. Use "hello" with a teacher or a stranger. good morning: Until about midday. good afternoon: From midday until about 6 p.m. good evening: From about 6 p.m. It is a greeting; "good night" is a farewell. name: Say "My name is Ana" or "I''m Ana" — never both together. nice to meet you: Only the first time you meet someone.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m1_lesson2_confusable_concepts', 'itm_l1_m1_lesson2', 'confusable_concepts', 'Brazil / Brazilian: No "the" before most country names. Japan / Japanese: Not "the Japan". the United Kingdom / British: This one DOES take "the" — like the Netherlands and the USA. be from: "I''m from" + country. Not "I''m come from". live in: "Live in" + city. "Be from" + country. They are not the same.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m2_lesson1_confusable_concepts', 'itm_l1_m2_lesson1', 'confusable_concepts', 'door: Open the door — not "open the light".', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m2_lesson2_confusable_concepts', 'itm_l1_m2_lesson2', 'confusable_concepts', 'this / these: "This" for one thing near you; "these" for more than one. that / those: "That" for one thing far away; "those" for more than one.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m3_lesson1_confusable_concepts', 'itm_l1_m3_lesson1', 'confusable_concepts', 'mother: "Mum" in everyday British speech. father: "Dad" in everyday British speech. cousin: One word for male and female in English. children: Irregular plural of "child".', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m3_lesson2_confusable_concepts', 'itm_l1_m3_lesson2', 'confusable_concepts', 'o''clock: Only on the hour. quarter to: Quarter to NINE means 8:45 — "to" looks forward to the next hour. wake up: Third person takes -s: she wakeS up. get up: Waking up and getting out of bed are two different things. have breakfast: Not "eat breakfast" in most British usage. go to work: No "the": go to work, go to school, go to bed. first, then, after that, finally: Sequence words for describing a routine in order.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m4_lesson1_confusable_concepts', 'itm_l1_m4_lesson1', 'confusable_concepts', 'egg: Countable: an egg, two eggs. apple: Countable. Takes "an", not "a". banana: Countable. rice: Uncountable: never "a rice" or "two rices". milk: Uncountable. water: Uncountable. bread: Uncountable in English, even though it is countable in many languages. cheese: Uncountable. chicken: Uncountable when it is food. some: Positive statements. any: Questions and negatives.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m4_lesson2_confusable_concepts', 'itm_l1_m4_lesson2', 'confusable_concepts', 'How much is...?: Singular and uncountable things. How much are...?: Plural things. Can I have..., please?: The polite request. "I want" sounds rude in a shop. Can I help you?: What the shop assistant says first. Here you are: Said when you hand something over. money: Uncountable: never "moneys". change: The money you get back. pay: Pay the bill — not "pay the money". shop: "Store" in American English. do the shopping: Not "make the shopping".', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m5_lesson1_confusable_concepts', 'itm_l1_m5_lesson1', 'confusable_concepts', 'opposite: On the other side of the road, facing it. between: Always with two places, joined by "and".', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m5_lesson2_confusable_concepts', 'itm_l1_m5_lesson2', 'confusable_concepts', 'Excuse me: How you open the question. Without it, it sounds like an order. go straight on: No "you": the imperative has no subject. cross the road: Not "pass the road". pharmacy: "Chemist''s" is also common in British English. minutes'' walk: How distance is usually given in a town. catch a bus: British usage; "take a bus" is more American.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m6_lesson1_confusable_concepts', 'itm_l1_m6_lesson1', 'confusable_concepts', 'tall: He IS tall — not "he has tall". short: Also used for hair: short black hair. hair: Uncountable: never "hairs" for the hair on your head. wear glasses: Not "use glasses". look like: "Look like" asks about appearance. "Look" alone means seem.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m6_lesson2_confusable_concepts', 'itm_l1_m6_lesson2', 'confusable_concepts', 'my / mine: "My" goes before a noun; "mine" stands alone. his: The same word both times — the only one that does this. her / hers: No apostrophe: hers, not her''s. big / small: Size comes before colour: big red, not red big.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m7_lesson1_confusable_concepts', 'itm_l1_m7_lesson1', 'confusable_concepts', 'study — studied: y becomes -ied after a consonant. play — played: y stays after a vowel: played, not "plaied". visit — visited: The -ed is a whole syllable here: vi-si-ted. yesterday: Goes with the past, never the present. didn''t: After didn''t, use the BASE verb: didn''t study, not "didn''t studied".', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m7_lesson2_confusable_concepts', 'itm_l1_m7_lesson2', 'confusable_concepts', 'make — made: "Make" for things you create; "do" for activities. Did you...?: Did + subject + BASE verb: "Did you go", not "Did you went". have a good time: Not "pass a good time". take a photo: Not "make a photo".', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m8_lesson1_confusable_concepts', 'itm_l1_m8_lesson1', 'confusable_concepts', 'can / can''t: Same form for every subject: she can, not "she cans". ride a bike: Ride a bike — not "drive a bike". play football: "Play" for games and sports. learn to: "Learn to" + verb.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m8_lesson2_confusable_concepts', 'itm_l1_m8_lesson2', 'confusable_concepts', 'going to: am/is/are + going to + BASE verb. A plan, not an ability. meet a friend: "Meet" for arranging to see someone — not "know". holiday: "Vacation" in American English.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m9_lesson1_confusable_concepts', 'itm_l1_m9_lesson1', 'confusable_concepts', 'headache: HAVE a headache. Not "I am headache". a cold: Catch a cold — not "take a cold". feel: FEEL + adjective. No "have" here: "I feel sick", not "I have sick". What''s the matter?: Also: How are you feeling?', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.'),
  ('ped_itm_l1_m9_lesson2_confusable_concepts', 'itm_l1_m9_lesson2', 'confusable_concepts', 'should / shouldn''t: Same form for every subject, and always + BASE verb. take medicine: Take medicine — not "drink medicine". feel better: Not "feel more good". That''s a good idea: How you accept advice.', 'derived_from_curriculum', 'The points at which this lesson''''s own vocabulary set warns that English is arbitrary.')ON CONFLICT (learning_item_id, field_key) DO UPDATE SET
INSERT INTO pedagogy_entries (id, learning_item_id, field_key, value, evidence_state, source) VALUES
('ped_l1_m1_l1_why', 'itm_l1_m1_lesson1', 'why_mistakes', 'Greeting systems are among the first things transferred wholesale from a first language, and the time-of-day boundaries differ between languages even where the words correspond. "Good night" as a greeting is the classic case: in many languages the evening greeting and the parting formula are one word.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m1_l2_why', 'itm_l1_m1_lesson2', 'why_mistakes', 'Article use with proper nouns is arbitrary in English and cannot be reasoned to. Learners whose first language uses articles with country names, or uses none at all, transfer the pattern and are right by accident or wrong by system.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m2_l1_why', 'itm_l1_m2_lesson1', 'why_mistakes', 'Existential "there" carries no meaning and agrees with the noun that follows rather than with itself, which is unlike almost any other English subject. Learners reasonably treat "there" as the subject and make the verb agree with it.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m2_l2_why', 'itm_l1_m2_lesson2', 'why_mistakes', 'Many languages have a two-term demonstrative system where English has a four-term one crossing distance with number. Learners default to the near term because it is the one they hear most.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m3_l1_why', 'itm_l1_m3_lesson1', 'why_mistakes', 'English kinship terms are fewer and less specific than in many languages — one word for cousin, no distinction between maternal and paternal lines. Learners look for a distinction that is not there and invent one.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m3_l2_why', 'itm_l1_m3_lesson2', 'why_mistakes', 'The third-person -s is the most persistent error in elementary English for learners of every first language. It carries no meaning the sentence needs, it is unstressed, and it is frequently inaudible in connected speech, so nothing in comprehension reinforces it.', 'established_pedagogy', 'Widely attested in ELT literature; not observed at this College.'),
('ped_l1_m4_l1_why', 'itm_l1_m4_lesson1', 'why_mistakes', 'Countability is a property of English nouns rather than of the things they name. Bread, advice and furniture are uncountable in English and countable in many languages, so the distinction has to be learned noun by noun and cannot be predicted from the world.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m4_l2_why', 'itm_l1_m4_lesson2', 'why_mistakes', 'Politeness in transactions is encoded grammatically in English — the interrogative request — where many languages encode it lexically or through intonation. A learner transferring their own system produces sentences that are grammatical and read as rude.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m5_l1_why', 'itm_l1_m5_lesson1', 'why_mistakes', 'Prepositions map poorly between languages and "opposite" and "in front of" are frequently merged. The confusion is spatial as well as lexical: what counts as facing depends on the road between.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m5_l2_why', 'itm_l1_m5_lesson2', 'why_mistakes', 'The English imperative has no subject pronoun, which reads as abrupt to learners from languages where the bare imperative is impolite. They supply a subject, or a modal, and the direction stops sounding like a direction.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m6_l1_why', 'itm_l1_m6_lesson1', 'why_mistakes', 'The split between BE for qualities and HAVE for features is arbitrary and differs between languages: several major languages use HAVE for age and hunger where English uses BE, and the transfer runs in both directions.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m6_l2_why', 'itm_l1_m6_lesson2', 'why_mistakes', 'English possessives agree with the POSSESSOR, not the possessed noun, which is the reverse of the Romance pattern. The apostrophe error in "her''s" is orthographic rather than grammatical and comes from the possessive ''s learned one lesson earlier.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m7_l1_why', 'itm_l1_m7_lesson1', 'why_mistakes', 'After "didn''t" the tense is already marked, so English drops it from the main verb. Learners who have just been taught to add -ed apply it consistently, which is the correct generalisation of the rule they were given and the wrong result.', 'established_pedagogy', 'Widely attested overgeneralisation; not observed at this College.'),
('ped_l1_m7_l2_why', 'itm_l1_m7_lesson2', 'why_mistakes', 'Irregular past forms cannot be derived and must be memorised, and the same double-marking problem returns in questions: "Did you went" is the regularisation of a rule correctly learned.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m8_l1_why', 'itm_l1_m8_lesson1', 'why_mistakes', 'Modals do not inflect, which contradicts the third-person -s rule taught five modules earlier. The error is a sign the earlier rule was learned well, and it resolves as the modal system is met more often.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m8_l2_why', 'itm_l1_m8_lesson2', 'why_mistakes', '"Going to" contains a verb of motion, so learners read it as movement and produce "going to going". Separating the structure from its literal parts is the whole difficulty of the form.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m9_l1_why', 'itm_l1_m9_lesson1', 'why_mistakes', 'English divides illness between HAVE for the condition and FEEL for the sensation, where many languages use one verb or express both with BE. The two patterns are taught together here because they are confused together.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m9_l2_why', 'itm_l1_m9_lesson2', 'why_mistakes', 'Advice is a face-threatening act, and learners either soften it out of existence or issue it as an imperative. "Should" is the calibrated middle and has no direct equivalent in many languages.', 'established_pedagogy', 'General ELT practice; not observed at this College.'),
('ped_l1_m10_why', 'itm_l1_m10_revlesson', 'why_mistakes', 'Recognition outruns production at every level, and most visibly at the first. A learner who can identify the right structure when told which one to look for may be unable to select it unprompted, which is what the revision lesson exists to expose before the examination does.', 'established_pedagogy', 'General ELT practice; not observed at this College.')
INSERT INTO pedagogy_entries (id, learning_item_id, field_key, value, evidence_state, source) VALUES
('ped_l1_m1_l1_int', 'itm_l1_m1_lesson1', 'intervention', 'Put the four greetings on the board against a clock face rather than a list. The boundary at six is the thing being taught; a list hides it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m1_l1_dd', 'itm_l1_m1_lesson1', 'differentiate_down', 'Let the learner answer with the greeting alone before adding the name. Two moves at once is the load, not either move.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m1_l1_st', 'itm_l1_m1_lesson1', 'stretch', 'Ask for the greeting a learner would use to a teacher, a shopkeeper and a friend, and for one word of justification. It anticipates the register work of Module 4.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m3_l2_int', 'itm_l1_m3_lesson2', 'intervention', 'When the third-person -s disappears, do not re-explain the rule — it is known. Have the learner read their own sentences aloud with a finger under each verb. The error is in production, not in knowledge, and only production practice moves it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m3_l2_alt', 'itm_l1_m3_lesson2', 'alternative_explanation', 'Frame it as agreement rather than as a verb ending: the -s belongs to he, she and it, and it moves onto the verb because English has nowhere else to put it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m3_l2_vis', 'itm_l1_m3_lesson2', 'visual_explanation', 'A clock face with the routine verbs placed around it, so the sequence words attach to positions rather than to an abstract order.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m3_l2_ana', 'itm_l1_m3_lesson2', 'analogy', 'The -s is a small label the third person carries everywhere, the way a name badge stays on whoever is wearing it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m3_l2_dd', 'itm_l1_m3_lesson2', 'differentiate_down', 'Restrict the routine to four events and to the first person. Add the third person only when the four are fluent.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m3_l2_st', 'itm_l1_m3_lesson2', 'stretch', 'Ask for someone else''s routine narrated in the third person and then contrasted with the learner''s own, which forces the -s to alternate within one piece.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m4_l1_int', 'itm_l1_m4_lesson1', 'intervention', 'Sort real or pictured items into two physical columns before any sentence is written. Countability is a property of the noun and has to be attached to the noun, not to a rule.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m4_l1_ana', 'itm_l1_m4_lesson1', 'analogy', 'Uncountable nouns are things you would weigh rather than count — but the analogy is a memory aid and not a test, because English breaks it, and saying so is part of teaching it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m4_l1_st', 'itm_l1_m4_lesson1', 'stretch', 'Ask for the two nouns on the list that are countable in the learner''s first language and uncountable in English. It makes the arbitrariness visible rather than merely stated.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m5_l2_int', 'itm_l1_m5_lesson2', 'intervention', 'If a learner adds "you" to the imperative, do not correct the form first. Give the direction back to them with the pronoun in it and let them hear the difference, then remove it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m5_l2_vis', 'itm_l1_m5_lesson2', 'visual_explanation', 'A single street drawn on the board, and every direction traced with a finger as it is spoken. Directions are a spatial task carried by language, and treating them as language alone loses half the lesson.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m5_l2_st', 'itm_l1_m5_lesson2', 'stretch', 'Give directions that are deliberately ambiguous and ask the partner to identify which step could be misread. It is the first evaluative act the level offers.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m6_l1_int', 'itm_l1_m6_lesson1', 'intervention', 'Two columns headed IS and HAS, and every new adjective or feature placed in one before it is used in a sentence.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m6_l1_dd', 'itm_l1_m6_lesson1', 'differentiate_down', 'Give a photograph and three fixed frames — "She is ___", "She has ___ hair", "He wears ___" — rather than free description. Choosing between IS and HAS is this lesson''s real difficulty, and the frames hold that choice still while the appearance vocabulary is learned.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m7_l1_int', 'itm_l1_m7_lesson1', 'intervention', 'Cover the negative sentences and ask what "didn''t" has already told the listener. Learners can usually answer "that it is past", which is the whole explanation for why the verb does not repeat it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m7_l1_ana', 'itm_l1_m7_lesson1', 'analogy', 'You do not write the date twice on the same envelope. "Didn''t" has already stamped it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m7_l1_fast', 'itm_l1_m7_lesson1', 'faster_explanation', 'One tense marker per sentence. "Didn''t" is holding it.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m7_l2_st', 'itm_l1_m7_lesson2', 'stretch', 'Ask for a weekend narrated with three irregular verbs and one negative, then for the same events as questions. Producing both directions is what makes the forms retrievable.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m8_l1_alt', 'itm_l1_m8_lesson1', 'alternative_explanation', 'Modals are a closed set that never change shape. If a learner asks why "can" does not take -s, the honest answer is that modals are the exception and the list is short enough to learn as a list.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m8_l2_int', 'itm_l1_m8_lesson2', 'intervention', 'When "going to going" appears, write "going to" as a single unit in a box and put the verb outside it. The problem is that the structure looks like the verb it precedes.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m9_l1_int', 'itm_l1_m9_lesson1', 'intervention', 'Two frames on the board — "I have a ___" and "I feel ___" — and every new word placed in one. The split is the lesson; the vocabulary is the vehicle.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m9_l2_st', 'itm_l1_m9_lesson2', 'stretch', 'Give a problem with two reasonable pieces of advice and ask which is better and why, in one sentence. It is the first time the level asks a learner to justify a choice rather than make one.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m10_int', 'itm_l1_m10_revlesson', 'intervention', 'If a learner can explain a rule but not select it, stop revising rules. Give unlabelled situations and ask only "which module?" until the mapping is quick, then return to production.', 'educational_expertise', 'Designed by the curriculum authors.'),
('ped_l1_m10_rem', 'itm_l1_m10_revlesson', 'remediation', 'Work backwards from the self-checks rather than forwards through the modules: the prompts the learner cannot answer name the modules to revise, and the traps name what to revise about them.', 'educational_expertise', 'Designed by the curriculum authors.')
